arguments.code:
# Event rates around newcomer arrival; compare 30s before and first 30s after, plus later period.
windows=[('pre','08:13:30','08:14:00'),('arrival','08:14:10','08:14:40'),('late','08:15:10','08:15:40')]
keys=['sched_switch','sched_wakeup','sched_waking','sched_stat_runtime','block_rq_issue','block_rq_complete','net_dev_xmit','net_if_receive_skb','syscall_entry_futex','syscall_exit_futex','sched_process_exit','sched_process_fork']
for label,a,b in windows:
 lo,hi=secs(a),secs(b); sub=df[(df.bucket_start_s>=lo)&(df.bucket_start_s<hi)]
 print(label, a,b)
 for k in keys:
  x=sub[sub.event==k]
  if len(x): print(k,int(x.n.sum()), 'rate/s',round(x.n.sum()/(hi-lo),1), 'top',x.groupby(['procname','pid_ns']).n.sum().nlargest(3).to_dict())

evs=['sched_switch','sched_waking','net_dev_xmit','net_if_receive_skb','block_dirty_buffer','syscall_entry_futex']; z=df[df.event.isin(evs)].copy(); windows={'pre':'08:13:30','drop':'08:14:10','recovery':'08:16:10'}; spans={'pre':('08:13:30','08:14:00'),'drop':('08:14:10','08:16:00'),'recovery':('08:16:10','08:16:50')};
for name,(a,b) in spans.items():
 lo,hi=secs(a),secs(b); g=z[(z.bucket_start_s>=lo)&(z.bucket_start_s<hi)].groupby('event').n.sum()/(hi-lo); print(name, a,b, 'rate/s'); print(g.to_string())

for e in ['sched_switch','sched_waking','sched_process_exec','sched_process_fork','sched_process_exit','block_rq_issue','block_rq_complete','syscall_entry_futex','net_dev_xmit']:
 print('\nEVENT',e)
 for line in get_lines(event=e,t0=secs('08:14:06'),t1=secs('08:14:07'),limit=4): print(line)

